mstore(0x00, 0xb12d13eb) revert(0x1c, 0x04) } } } function forceSafeTransferETH(address to, uint256 amount, uint256 gasStipend) internal { assembly { if lt(selfbalance(), amount) { mstore(0x00, 0xb12d13eb) revert(0x1c, 0x04) } if iszero(call(gasStipend, to, amount, gas(), 0x00, gas(), 0x00)) { mstore(0x00, to) mstore8(0x0b, 0x73) mstore8(0x20, 0xff) if iszero(create(amount, 0x0b, 0x16)) { returndatacopy(gas(), returndatasize(), shr(20, gas())) } } } } function forceSafeTransferAllETH(address to, uint256 gasStipend) internal { assembly { if iszero(call(gasStipend, to, selfbalance(), gas(), 0x00, gas(), 0x00)) { mstore(0x00, to) mstore8(0x0b, 0x73) mstore8(0x20, 0xff) if iszero(create(selfbalance(), 0x0b, 0x16)) { returndatacopy(gas(), returndatasize(), shr(20, gas())) } } } } function forceSafeTransferETH(address to, uint256 amount) internal { assembly { if lt(selfbalance(), amount) { mstore(0x00, 0xb12d13eb) revert(0x1c, 0x04) } if iszero(call(GAS_STIPEND_NO_GRIEF, to, amount, gas(), 0x00, gas(), 0x00)) { mstore(0x00, to) mstore8(0x0b, 0x73) mstore8(0x20, 0xff) if iszero(create(amount, 0x0b, 0x16)) { returndatacopy(gas(), returndatasize(), shr(20, gas())) } } } } function forceSafeTransferAllETH(address to) internal { assembly { if iszero(call(GAS_STIPEND_NO_GRIEF, to, selfbalance(), gas(), 0x00, gas(), 0x00)) { mstore(0x00, to) mstore8(0x0b, 0x73) mstore8(0x20, 0xff) if iszero(create(selfbalance(), 0x0b, 0x16)) { returndatacopy(gas(), returndatasize(), shr(20, gas())) } } } } function trySafeTransferETH(address to, uint256 amount, uint256 gasStipend) internal returns (bool success) { assembly { success := call(gasStipend, to, amount, gas(), 0x00, gas(), 0x00) } } function trySafeTransferAllETH(address to, uint256 gasStipend) internal returns (bool success) { assembly { success := call(gasStipend, to, selfbalance(), gas(), 0x00, gas(), 0x00) } } function safeTransferFrom(address token, address from, address to, uint256 amount) internal { assembly { let m := mload(0x40) mstore(0x60, amount) mstore(0x40, to) mstore(0x2c, shl(96, from)) mstore(0x0c, 0x23b872dd000000000000000000000000) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x1c, 0x64, 0x00, 0x20) ) ) { mstore(0x00, 0x7939f424) revert(0x1c, 0x04) } mstore(0x60, 0) mstore(0x40, m) } } function safeTransferAllFrom(address token, address from, address to) internal returns (uint256 amount) { assembly { let m := mload(0x40) mstore(0x40, to) mstore(0x2c, shl(96, from)) mstore(0x0c, 0x70a08231000000000000000000000000) if iszero( and( gt(returndatasize(), 0x1f), staticcall(gas(), token, 0x1c, 0x24, 0x60, 0x20) ) ) { mstore(0x00, 0x7939f424) revert(0x1c, 0x04) } mstore(0x00, 0x23b872dd) amount := mload(0x60) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x1c, 0x64, 0x00, 0x20) ) ) { mstore(0x00, 0x7939f424) revert(0x1c, 0x04) } mstore(0x60, 0) mstore(0x40, m) } } function safeTransfer(address token, address to, uint256 amount) internal { assembly { mstore(0x14, to) mstore(0x34, amount) mstore(0x00, 0xa9059cbb000000000000000000000000) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x10, 0x44, 0x00, 0x20) ) ) { mstore(0x00, 0x90b8ec18) revert(0x1c, 0x04) } mstore(0x34, 0) } } function safeTransferAll(address token, address to) internal returns (uint256 amount) { assembly { mstore(0x00, 0x70a08231) mstore(0x20, address()) if iszero( and( gt(returndatasize(), 0x1f), staticcall(gas(), token, 0x1c, 0x24, 0x34, 0x20) ) ) { mstore(0x00, 0x90b8ec18) revert(0x1c, 0x04) } mstore(0x14, to) amount := mload(0x34) mstore(0x00, 0xa9059cbb000000000000000000000000) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x10, 0x44, 0x00, 0x20) ) ) { mstore(0x00, 0x90b8ec18) revert(0x1c, 0x04) } mstore(0x34, 0) } } function safeApprove(address token, address to, uint256 amount) internal { assembly { mstore(0x14, to) mstore(0x34, amount) mstore(0x00, 0x095ea7b3000000000000000000000000) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x10, 0x44, 0x00, 0x20) ) ) { mstore(0x00, 0x3e3f8f73) revert(0x1c, 0x04) } mstore(0x34, 0) } } function safeApproveWithRetry(address token, address to, uint256 amount) internal { assembly { mstore(0x14, to) mstore(0x34, amount) mstore(0x00, 0x095ea7b3000000000000000000000000) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x10, 0x44, 0x00, 0x20) ) ) { mstore(0x34, 0) mstore(0x00, 0x095ea7b3000000000000000000000000) pop(call(gas(), token, 0, 0x10, 0x44, 0x00, 0x00)) mstore(0x34, amount) if iszero( and( or(eq(mload(0x00), 1), iszero(returndatasize())), call(gas(), token, 0, 0x10, 0x44, 0x00, 0x20) ) ) { mstore(0x00, 0x3e3f8f73) revert(0x1c, 0x04) } } mstore(0x34, 0) } } function balanceOf(address token, address account) internal view returns (uint256 amount) { assembly { mstore(0x14, account) mstore(0x00, 0x70a08231000000000000000000000000) amount := mul( mload(0x20), and( gt(returndatasize(), 0x1f), staticcall(gas(), token, 0x10, 0x24, 0x20, 0x20) ) ) } } } abstract contract ERC20 { event Transfer(address indexed from, address indexed to, uint256 amount); event Approval(address indexed owner, address indexed spender, uint256 amount); string public name; string public symbol; uint8 public immutable decimals; uint256 public totalSupply; mapping(address => uint256) public balanceOf; mapping(address => mapping(address => uint256)) public allowance; uint256 internal immutable INITIAL_CHAIN_ID; bytes32 internal immutable INITIAL_DOMAIN_SEPARATOR; mapping(address => uint256) public nonces; constructor( string memory _name, string memory _symbol, uint8 _decimals ) { name = _name; symbol = _symbol; decimals = _decimals; INITIAL_CHAIN_ID = block.chainid; INITIAL_DOMAIN_SEPARATOR = computeDomainSeparator(); } function approve(address spender, uint256 amount) public virtual returns (bool) { allowance[msg.sender][spender] = amount; emit Approval(msg.sender, spender, amount); return true; } function transfer(address to, uint256 amount) public virtual returns (bool) { balanceOf[msg.sender] -= amount; unchecked { balanceOf[to] += amount; } emit Transfer(msg.sender, to, amount); return true; } function transferFrom( address from, address to, uint256 amount ) public virtual returns (bool) { uint256 allowed = allowance[from][msg.sender]; if (allowed != type(uint256).max) allowance[from][msg.sender] = allowed - amount; balanceOf[from] -= amount; unchecked { balanceOf[to] += amount; } emit Transfer(from, to, amount); return true; } function permit( address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s ) public virtual { require(deadline >= block.timestamp, "PERMIT_DEADLINE_EXPIRED"); unchecked { address recoveredAddress = ecrecover( keccak256( abi.encodePacked( "\x19\x01", DOMAIN_SEPARATOR(), keccak256( abi.encode( keccak256( "Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)" ), owner, spender, value, nonces[owner]++, deadline ) ) ) ), v, r, s ); require(recoveredAddress != address(0) && recoveredAddress == owner, "INVALID_SIGNER"); allowance[recoveredAddress][spender] = value; } emit Approval(owner, spender, value); } function DOMAIN_SEPARATOR() public view virtual returns (bytes32) { return block.chainid == INITIAL_CHAIN_ID ? INITIAL_DOMAIN_SEPARATOR : computeDomainSeparator(); } function computeDomainSeparator() internal view virtual returns (bytes32) { return keccak256( abi.encode( keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"), keccak256(bytes(name)), keccak256("1"), block.chainid, address(this) ) ); } function _mint(address to, uint256 amount) internal virtual { totalSupply += amount; unchecked { balanceOf[to] += amount; } emit Transfer(address(0), to, amount); } function _burn(address from, uint256 amount) internal virtual { balanceOf[from] -= amount; unchecked { totalSupply -= amount; } emit Transfer(from, address(0), amount); } } abstract contract ERC721 { event Transfer(address indexed from, address indexed to, uint256 indexed id); event Approval(address indexed owner, address indexed spender, uint256 indexed id); event ApprovalForAll(address indexed owner, address indexed operator, bool approved); string public name; string public symbol; function tokenURI(uint256 id) public view virtual returns (string memory); mapping(uint256 => address) internal _ownerOf; mapping(address => uint256) internal _balanceOf; function ownerOf(uint256 id) public view virtual returns (address owner) { require((owner = _ownerOf[id]) != address(0), "NOT_MINTED"); } function balanceOf(address owner) public view virtual returns (uint256) { require(owner != address(0), "ZERO_ADDRESS"); return _balanceOf[owner]; } mapping(uint256 => address) public getApproved; mapping(address => mapping(address => bool)) public isApprovedForAll; constructor(string memory _name, string memory _symbol) { name = _name; symbol = _symbol; } function approve(address spender, uint256 id) public virtual { address owner = _ownerOf[id]; require(msg.sender == owner || isApprovedForAll[owner][msg.sender], "NOT_AUTHORIZED"); getApproved[id] = spender; emit Approval(owner, spender, id); } function setApprovalForAll(address operator, bool approved) public virtual { isApprovedForAll[msg.sender][operator] = approved; emit ApprovalForAll(msg.sender, operator, approved); } function transferFrom( address from, address to, uint256 id ) public virtual { require(from == _ownerOf[id], "WRONG_FROM"); require(to != address(0), "INVALID_RECIPIENT"); require( msg.sender == from || isApprovedForAll[from][msg.sender] || msg.sender == getApproved[id], "NOT_AUTHORIZED" ); unchecked { _balanceOf[from]--; _balanceOf[to]++; } _ownerOf[id] = to; delete getApproved[id]; emit Transfer(from, to, id); } function safeTransferFrom( address from, address to, uint256 id ) public virtual { transferFrom(from, to, id); require( to.code.length == 0 || ERC721TokenReceiver(to).onERC721Received(msg.sender, from, id, "") == ERC721TokenReceiver.onERC721Received.selector, "UNSAFE_RECIPIENT" ); } function safeTransferFrom( address from, address to, uint256 id, bytes calldata data ) public virtual { transferFrom(from, to, id); require( to.code.length == 0 || ERC721TokenReceiver(to).onERC721Received(msg.sender, from, id, data) == ERC721TokenReceiver.onERC721Received.selector, "UNSAFE_RECIPIENT" ); } function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) { return interfaceId == 0x01ffc9a7 || interfaceId == 0x80ac58cd || interfaceId == 0x5b5e139f; } function _mint(address to, uint256 id) internal virtual { require(to != address(0), "INVALID_RECIPIENT"); require(_ownerOf[id] == address(0), "ALREADY_MINTED"); unchecked { _balanceOf[to]++; } _ownerOf[id] = to; emit Transfer(address(0), to, id); } function _burn(uint256 id) internal virtual { address owner = _ownerOf[id]; require(owner != address(0), "NOT_MINTED"); unchecked { _balanceOf[owner]--; } delete _ownerOf[id]; delete getApproved[id]; emit Transfer(owner, address(0), id); } function _safeMint(address to, uint256 id) internal virtual { _mint(to, id); require( to.code.length == 0 || ERC721TokenReceiver(to).onERC721Received(msg.sender, address(0), id, "") == ERC721TokenReceiver.onERC721Received.selector, "UNSAFE_RECIPIENT" ); } function _safeMint( address to, uint256 id, bytes memory data ) internal virtual { _mint(to, id); require( to.code.length == 0 || ERC721TokenReceiver(to).onERC721Received(msg.sender, address(0), id, data) == ERC721TokenReceiver.onERC721Received.selector, "UNSAFE_RECIPIENT" ); } } abstract contract ERC721TokenReceiver { function onERC721Received( address, address, uint256, bytes calldata ) external virtual returns (bytes4) { return ERC721TokenReceiver.onERC721Received.selector; } } struct GasParams { uint256 gasLimit; uint256 remoteBranchExecutionGas; } struct Deposit { uint8 status; address owner; address[] hTokens; address[] tokens; uint256[] amounts; uint256[] deposits; } struct DepositInput { address hToken; address token; uint256 amount; uint256 deposit; } struct DepositMultipleInput { address[] hTokens; address[] tokens; uint256[] amounts; uint256[] deposits; } struct DepositMultipleParams { uint8 numberOfAssets; uint32 depositNonce; address[] hTokens; address[] tokens; uint256[] amounts; uint256[] deposits; } struct DepositParams { uint32 depositNonce; address hToken; address token; uint256 amount; uint256 deposit; } struct Settlement { uint16 dstChainId; uint80 status; address owner; address recipient; address[] hTokens; address[] tokens; uint256[] amounts; uint256[] deposits; } struct SettlementInput { address globalAddress; uint256 amount; uint256 deposit; } struct SettlementMultipleInput { address[] globalAddresses; uint256[] amounts; uint256[] deposits; } struct SettlementParams { uint32 settlementNonce; address recipient; address hToken; address token; uint256 amount; uint256 deposit; } struct SettlementMultipleParams { uint8 numberOfAssets; address recipient; uint32 settlementNonce; address[] hTokens; address[] tokens; uint256[] amounts; uint256[] deposits; } interface IERC20hTokenRoot { function localChainId() external view returns (uint16); function factoryAddress() external view returns (address); function getTokenBalance(uint256 chainId) external view returns (uint256); function mint(address to, uint256 amount, uint256 chainId) external returns (bool); function burn(address from, uint256 amount, uint256 chainId) external; error UnrecognizedPort(); } interface ILayerZeroReceiver { function lzReceive(uint16 _srcChainId, bytes calldata _srcAddress, uint64 _nonce, bytes calldata _payload) external; } interface IERC1155Receiver is IERC165 { function onERC1155Received( address operator, address from, uint256 id, uint256 value, bytes calldata data ) external returns (bytes4); function onERC1155BatchReceived( address operator, address from, uint256[] calldata ids, uint256[] calldata values, bytes calldata data ) external returns (bytes4); } abstract contract ERC165 is IERC165 { function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) { return interfaceId == type(IERC165).interfaceId; } } struct Call { address target; bytes callData; } struct PayableCall { address target; bytes callData; uint256 value; } interface IVirtualAccount is IERC721Receiver { function userAddress() external view returns (address); function localPortAddress() external view returns (address); function withdrawNative(uint256 _amount) external; function withdrawERC20(address _token, uint256 _amount) external; function withdrawERC721(address _token, uint256 _tokenId) external; function call(Call[] calldata callInput) external returns (bytes[] memory); function payableCall(PayableCall[] calldata calls) external payable returns (bytes[] memory); error CallFailed(); error UnauthorizedCaller(); } interface IRootBridgeAgent is ILayerZeroReceiver { function settlementNonce() external view returns (uint32 nonce); function getSettlementEntry(uint32 _settlementNonce) external view returns (Settlement memory); function bridgeAgentExecutorAddress() external view returns (address); function factoryAddress() external view returns (address); function getBranchBridgeAgent(uint256 _chainId) external view returns (address); function isBranchBridgeAgentAllowed(uint256 _chainId) external view returns (bool); function getFeeEstimate( uint256 _gasLimit, uint256 _remoteBranchExecutionGas, bytes calldata _payload, uint16 _dstChainId ) external view returns (uint256 _fee); function callOut( address payable _refundee, address _recipient, uint16 _dstChainId, bytes memory _params, GasParams calldata _gParams ) external payable; function callOutAndBridge( address payable _refundee, address _recipient, uint16 _dstChainId, bytes calldata _params, SettlementInput calldata _sParams, GasParams calldata _gParams, bool _hasFallbackToggled ) external payable; function callOutAndBridgeMultiple( address payable _refundee, address _recipient, uint16 _dstChainId, bytes calldata _params, SettlementMultipleInput calldata _sParams, GasParams calldata _gParams, bool _hasFallbackToggled ) external payable; function retrySettlement( uint32 _settlementNonce, address _recipient, bytes calldata _params, GasParams calldata _gParams, bool _hasFallbackToggled ) external payable; function retrieveSettlement(uint32 _settlementNonce, GasParams calldata _gParams) external payable; function redeemSettlement(uint32 _depositNonce) external; function bridgeIn(address _recipient, DepositParams memory _dParams, uint256 _srcChainId) external; function bridgeInMultiple(address _recipient, DepositMultipleParams calldata _dParams, uint256 _srcChainId) external; function lzReceiveNonBlocking( address _endpoint, uint16 _srcChainId, bytes calldata _srcAddress, bytes calldata _payload ) external; function approveBranchBridgeAgent(uint256 _branchChainId) external; function syncBranchBridgeAgent(address _newBranchBridgeAgent, uint256 _branchChainId) external; event LogExecute(uint256 indexed depositNonce, uint256 indexed srcChainId); event LogFallback(uint256 indexed settlementNonce, uint256 indexed dstChainId); error ExecutionFailure(); error GasErrorOrRepeatedTx(); error AlreadyExecutedTransaction(); error UnknownFlag(); error NotDao(); error LayerZeroUnauthorizedEndpoint(); error LayerZeroUnauthorizedCaller(); error AlreadyAddedBridgeAgent(); error UnrecognizedExecutor(); error UnrecognizedPort(); error UnrecognizedBridgeAgent(); error UnrecognizedLocalBridgeAgent(); error UnrecognizedBridgeAgentManager(); error UnrecognizedRouter(); error UnrecognizedUnderlyingAddress(); error UnrecognizedLocalAddress(); error SettlementRetryUnavailable(); error SettlementRetryUnavailableUseCallout(); error SettlementRedeemUnavailable(); error SettlementRetrieveUnavailable(); error NotSettlementOwner(); error InsufficientBala